// TikTok OAuth v2 — Exchange authorisation code for access + refresh tokens
// TikTok for Developers: https://developers.tiktok.com/doc/oauth-user-access-token-management
// NEVER use this.getCredentials() — use $env.VARIABLE_NAME
// Required env vars: TIKTOK_CLIENT_KEY, TIKTOK_CLIENT_SECRET

const body = $input.first().json.body || $input.first().json;
const code        = body.code;
const memberEmail = body.member_email || '';
const codeVerifier = body.code_verifier || '';

if (!code) {
  throw new Error('Missing authorisation code');
}

const clientKey    = $env.TIKTOK_CLIENT_KEY;
const clientSecret = $env.TIKTOK_CLIENT_SECRET;

// TikTok v2 token exchange uses x-www-form-urlencoded
const tokenParams = new URLSearchParams({
  client_key:    clientKey,
  client_secret: clientSecret,
  code:          code,
  grant_type:    'authorization_code',
  redirect_uri:  'https://brief.one-empire.com/tiktok/callback'
});

if (codeVerifier) {
  tokenParams.set('code_verifier', codeVerifier);
}

let tokenData;
try {
  const tokenRes = await $helpers.httpRequest({
    method: 'POST',
    url: 'https://open.tiktokapis.com/v2/oauth/token/',
    headers: {
      'Content-Type': 'application/x-www-form-urlencoded',
      'Cache-Control': 'no-cache'
    },
    body: tokenParams.toString()
  });
  tokenData = typeof tokenRes === 'string' ? JSON.parse(tokenRes) : tokenRes;
} catch (e) {
  throw new Error('TikTok token exchange failed: ' + e.message);
}

if (tokenData.error) {
  throw new Error('TikTok error: ' + (tokenData.error_description || tokenData.error));
}

const accessToken    = tokenData.access_token;
const refreshToken   = tokenData.refresh_token || null;
const openId         = tokenData.open_id || '';
const expiresIn      = tokenData.expires_in || 86400;
const refreshExpires = tokenData.refresh_expires_in || 31536000;

// Fetch TikTok user info
let displayName = '';
let avatarUrl   = '';
try {
  const userRes = await $helpers.httpRequest({
    method: 'GET',
    url: 'https://open.tiktokapis.com/v2/user/info/?fields=display_name,avatar_url',
    headers: { 'Authorization': `Bearer ${accessToken}` }
  });
  const userData = typeof userRes === 'string' ? JSON.parse(userRes) : userRes;
  if (userData.data && userData.data.user) {
    displayName = userData.data.user.display_name || '';
    avatarUrl   = userData.data.user.avatar_url || '';
  }
} catch (e) {
  // Non-fatal
}

const now             = new Date();
const expiresAt       = new Date(now.getTime() + expiresIn * 1000);
const refreshExpiresAt = new Date(now.getTime() + refreshExpires * 1000);

return [{
  json: {
    member_email:          memberEmail,
    tiktok_open_id:        openId,
    tiktok_name:           displayName,
    access_token:          accessToken,
    refresh_token:         refreshToken,
    expires_in:            expiresIn,
    refresh_expires_in:    refreshExpires,
    token_stored_at:       now.toISOString(),
    token_expires_at:      expiresAt.toISOString(),
    refresh_expires_at:    refreshExpiresAt.toISOString(),
    is_active:             true
  }
}];

// Store TikTok token in Supabase
// NEVER use this.getCredentials() — use $env.VARIABLE_NAME

const data = $input.first().json;
const supabaseUrl = 'https://gsqcsyepztcmrvzxevhw.supabase.co';
const serviceKey  = $env.SUPABASE_SERVICE_KEY;

if (!data.member_email) {
  throw new Error('member_email is required');
}

const payload = {
  member_email:       data.member_email,
  tiktok_open_id:     data.tiktok_open_id,
  tiktok_name:        data.tiktok_name,
  access_token:       data.access_token,
  refresh_token:      data.refresh_token,
  expires_in:         data.expires_in,
  refresh_expires_in: data.refresh_expires_in,
  token_stored_at:    data.token_stored_at,
  token_expires_at:   data.token_expires_at,
  refresh_expires_at: data.refresh_expires_at,
  is_active:          true
};

try {
  await $helpers.httpRequest({
    method: 'POST',
    url: `${supabaseUrl}/rest/v1/tiktok_tokens`,
    headers: {
      'Content-Type':  'application/json',
      'apikey':        serviceKey,
      'Authorization': `Bearer ${serviceKey}`,
      'Prefer':        'resolution=merge-duplicates'
    },
    body: JSON.stringify(payload)
  });
  return [{ json: { success: true, message: 'TikTok token stored', member_email: data.member_email } }];
} catch (e) {
  throw new Error('Failed to store TikTok token: ' + e.message);
}
